parameters.jsCode:
const llm = $input.first().json;
const raw = String(llm.text || llm.output || '').trim();
const clean = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let obj = null, ok = false;
try {
  obj = JSON.parse(clean);
  ok = obj && typeof obj.asunto_principal === 'string' && Array.isArray(obj.puntos_clave) && typeof obj.accion_requerida === 'string';
} catch (e) {}
if (!ok) return [{ json: { ok: false, motivo: 'El modelo no devolvió el JSON esperado' } }];

const resumen = { asunto_principal: obj.asunto_principal, puntos_clave: obj.puntos_clave, accion_requerida: obj.accion_requerida };
const hist = $('Leer historial').first().json;
const textoUsuario = (hist.messages || [])
  .filter(m => (m.id || []).includes('HumanMessage'))
  .map(m => (m.kwargs ? m.kwargs.content : m.content) || '')
  .join('\n');
const ctx = $('Contexto de sesión').first().json;
let nombre = ctx.user_name && ctx.user_name !== 'No informado' ? ctx.user_name : '';
const mt = textoUsuario.match(/(?:[Mm]e llamo|[Mm]i nombre es)\s+([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+)/);
if (mt) nombre = mt[1];
const worker = $('Worker OK?').first().json.worker;

return [{ json: {
  ok: true,
  session_id: ctx.session_id,
  fecha: new Date().toISOString(),
  resumen_json: JSON.stringify(resumen),
  estado: worker === 'derivacion' ? 'Derivado' : 'En curso',
  datos_clave: JSON.stringify({ nombre: nombre || 'No informado', canal: ctx.canal, mensajes_en_sesion: hist.messagesCount })
} }];

